// Robin is warm if there are no insults, or exactly one insult and an apology occurs after it.
function visible(actions) {
  let insults = 0;
  let lastInsult = -1;
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "insult") {
      insults++;
      lastInsult = i;
    }
  }
  if (insults === 0) return { mood: "warm" };
  if (insults !== 1) return { mood: "cold" };
  for (let i = lastInsult + 1; i < actions.length; i++) {
    if (actions[i] === "apologise") return { mood: "warm" };
  }
  return { mood: "cold" };
}

// Robin is warm if there are no insults, or if she ends with an apology and never had two insults in a row.
function visible(actions) {
  let insults = 0;
  let doubleInsult = false;
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "insult") {
      insults++;
      if (i > 0 && actions[i - 1] === "insult") doubleInsult = true;
    }
  }
  if (insults === 0) return { mood: "warm" };
  const last = actions[actions.length - 1];
  if (last === "apologise" && !doubleInsult) return { mood: "warm" };
  return { mood: "cold" };
}

