function visible(actions) {
  let grudge = 0;
  let hasApology = false;
  for (const action of actions) {
    if (action === "insult") {
      grudge += 1;
    } else if (action === "apologise") {
      hasApology = true;
      if (grudge > 0) grudge -= 1;
    } else if (action === "gift") {
      if (grudge > 0) {
        if (!hasApology) {
          grudge = Math.max(0, grudge - 2);
